    static Dictionary<char, int> semiBold, bold, black;

    /// <summary>Width in canvas units of <paramref name="text"/> set in Aileron <paramref name="weight"/>
    /// ("SemiBold", "Bold" or "Black", any case) at <paramref name="sizeU"/> units. A character the font
    /// does not map throws.</summary>
    public static float Width(string text, string weight, float sizeU)
    {
        if (text == null) throw new ArgumentNullException(nameof(text));
        Dictionary<char, int> table = Table(weight);
        long total = 0;
        foreach (char c in text)
        {
            if (!table.TryGetValue(c, out int advance))
                throw new ArgumentException("Aileron has no glyph for U+" + ((int)c).ToString("X4") + " in \"" + text + "\"");
            total += advance;
        }
        return total * sizeU / UnitsPerEm;
    }

    /// <summary>True when Aileron maps <paramref name="c"/> (every weight has the same set).</summary>
    public static bool Has(char c) => Table("Bold").ContainsKey(c);

    static Dictionary<char, int> Table(string weight)
    {
        switch ((weight ?? string.Empty).ToLowerInvariant())
        {
            case "semibold": return semiBold ?? (semiBold = Build(SemiBoldAdvances));
            case "bold": return bold ?? (bold = Build(BoldAdvances));
            case "black": return black ?? (black = Build(BlackAdvances));
            default: throw new ArgumentException("Unknown Aileron weight '" + weight + "' (SemiBold, Bold or Black)");
        }
    }

    static Dictionary<char, int> Build(int[] advances)
    {
        var table = new Dictionary<char, int>(Characters.Length);
        for (int i = 0; i < Characters.Length; i++) table[Characters[i]] = advances[i];
        return table;
    }
